      __style.textContent = "/* ============================================================\n   DSH Tool Config Studio — theme\n   Dark, quiet, high-contrast; tuned for the DSH web shell.\n   ============================================================ */\n\n:root {\n  --tcs-bg: #0d1017;\n  --tcs-panel: #141924;\n  --tcs-panel-2: #10151f;\n  --tcs-border: #242d3d;\n  --tcs-border-soft: #1b2331;\n  --tcs-text: #e8ebf0;\n  --tcs-text-dim: #98a2b3;\n  --tcs-text-faint: #677182;\n  --tcs-accent: #5b9dff;\n  --tcs-accent-soft: rgba(91, 157, 255, 0.14);\n  --tcs-ok: #42be65;\n  --tcs-danger: #f0554d;\n  --tcs-danger-soft: rgba(240, 85, 77, 0.12);\n  --tcs-warn: #d29922;\n  --tcs-mono: ui-monospace, \"SF Mono\", SFMono-Regular, Menlo, Consolas, \"Liberation Mono\", monospace;\n  --tcs-radius: 10px;\n  --tcs-shadow: 0 1px 2px rgba(0, 0, 0, 0.4);\n}\n\n/* Panel root rendered into the DSH main slot. The host gives the slot a\n   bounded region, so the panel itself is the scroll container (same\n   convention as DSH's own plugin-manager main page: height: 100% +\n   overflow auto). In a standalone page the container has no definite\n   height, so this degrades to normal document flow. */\n.tcs-root {\n  box-sizing: border-box;\n  height: 100%;\n  overflow-y: auto;\n  overscroll-behavior: contain;\n}\n\n.tcs {\n  max-width: 980px;\n  margin: 0 auto;\n  padding: 28px 20px 56px;\n  color: var(--tcs-text);\n  font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, \"Helvetica Neue\", Arial,\n    \"PingFang SC\", \"Microsoft YaHei\", sans-serif;\n  font-size: 14px;\n  line-height: 1.5;\n}\n\n/* ------------------------------------------------------------ header */\n\n.tcs-header {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 20px;\n  flex-wrap: wrap;\n}\n\n.tcs-title {\n  margin: 0;\n  font-size: 20px;\n  font-weight: 650;\n  letter-spacing: 0.2px;\n}\n\n.tcs-subtitle {\n  margin: 6px 0 0;\n  max-width: 52ch;\n  color: var(--tcs-text-dim);\n  font-size: 13px;\n}\n\n.tcs-header-actions {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  flex-wrap: wrap;\n}\n\n.tcs-search {\n  width: 260px;\n  max-width: 100%;\n  padding: 8px 12px;\n  border: 1px solid var(--tcs-border);\n  border-radius: 8px;\n  background: var(--tcs-panel-2);\n  color: var(--tcs-text);\n  font: inherit;\n  font-size: 13px;\n  outline: none;\n}\n\n.tcs-search:focus {\n  border-color: var(--tcs-accent);\n  box-shadow: 0 0 0 3px var(--tcs-accent-soft);\n}\n\n/* ------------------------------------------------------------ buttons */\n\n.tcs-btn {\n  font: inherit;\n  font-size: 13px;\n  padding: 8px 14px;\n  border-radius: 8px;\n  border: 1px solid var(--tcs-border);\n  background: var(--tcs-panel);\n  color: var(--tcs-text);\n  cursor: pointer;\n  transition: border-color 120ms ease, background 120ms ease;\n}\n\n.tcs-btn:hover {\n  border-color: var(--tcs-accent);\n  background: var(--tcs-accent-soft);\n}\n\n.tcs-btn-danger {\n  color: var(--tcs-danger);\n  border-color: rgba(240, 85, 77, 0.4);\n  background: transparent;\n}\n\n.tcs-btn-danger:hover {\n  color: var(--tcs-danger);\n  border-color: var(--tcs-danger);\n  background: var(--tcs-danger-soft);\n}\n\n.tcs-btn-ghost {\n  background: transparent;\n  border-color: transparent;\n  color: var(--tcs-text-dim);\n  padding: 4px 8px;\n}\n\n.tcs-btn-ghost:hover {\n  color: var(--tcs-text);\n  background: var(--tcs-accent-soft);\n  border-color: transparent;\n}\n\n/* ------------------------------------------------------------ main */\n\n.tcs-count {\n  margin: 22px 2px 10px;\n  color: var(--tcs-text-faint);\n  font-size: 12px;\n  text-transform: uppercase;\n  letter-spacing: 0.8px;\n}\n\n.tcs-group {\n  margin-top: 22px;\n}\n\n.tcs-group-title {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin: 0 2px 10px;\n  font-size: 12px;\n  font-weight: 600;\n  color: var(--tcs-text-dim);\n  text-transform: uppercase;\n  letter-spacing: 0.9px;\n}\n\n.tcs-group-count {\n  font-size: 11px;\n  color: var(--tcs-text-faint);\n  border: 1px solid var(--tcs-border-soft);\n  border-radius: 999px;\n  padding: 0 7px;\n  line-height: 16px;\n}\n\n.tcs-empty {\n  margin-top: 32px;\n  padding: 40px 20px;\n  text-align: center;\n  color: var(--tcs-text-dim);\n  border: 1px dashed var(--tcs-border);\n  border-radius: var(--tcs-radius);\n}\n\n/* ------------------------------------------------------------ tool rows */\n\n.tcs-tool {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 14px;\n  padding: 11px 14px;\n  margin-bottom: 8px;\n  border: 1px solid var(--tcs-border-soft);\n  border-radius: var(--tcs-radius);\n  background: var(--tcs-panel);\n  cursor: pointer;\n  user-select: none;\n  box-shadow: var(--tcs-shadow);\n  transition: border-color 120ms ease, background 120ms ease;\n}\n\n.tcs-tool:hover {\n  border-color: var(--tcs-border);\n  background: #171e2b;\n}\n\n.tcs-tool:focus-visible {\n  outline: 2px solid var(--tcs-accent);\n  outline-offset: 1px;\n}\n\n.tcs-tool-wrap .tcs-tool {\n  border: 1px solid var(--tcs-border);\n  border-bottom: none;\n  border-radius: var(--tcs-radius) var(--tcs-radius) 0 0;\n  margin-bottom: 0;\n}\n\n.tcs-tool-wrap .tcs-detail {\n  border: 1px solid var(--tcs-border);\n  border-top: none;\n  border-radius: 0 0 var(--tcs-radius) var(--tcs-radius);\n  margin-bottom: 8px;\n  background: var(--tcs-panel-2);\n  box-shadow: var(--tcs-shadow);\n}\n\n.tcs-tool-main {\n  display: flex;\n  align-items: baseline;\n  gap: 12px;\n  min-width: 0;\n  flex: 1;\n}\n\n.tcs-tool-name {\n  font-family: var(--tcs-mono);\n  font-size: 13px;\n  color: var(--tcs-accent);\n  white-space: nowrap;\n}\n\n.tcs-tool-text {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n}\n\n.tcs-tool-title {\n  font-size: 13.5px;\n  font-weight: 600;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.tcs-tool-summary {\n  font-size: 12px;\n  color: var(--tcs-text-dim);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.tcs-tool-meta {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex: none;\n}\n\n.tcs-chevron {\n  color: var(--tcs-text-faint);\n  transition: transform 140ms ease;\n  font-size: 12px;\n}\n\n.tcs-tool.is-expanded .tcs-chevron {\n  transform: rotate(90deg);\n}\n\n/* chips & pills */\n\n.tcs-chip {\n  font-size: 11px;\n  color: var(--tcs-text-dim);\n  border: 1px solid var(--tcs-border-soft);\n  border-radius: 999px;\n  padding: 1px 8px;\n  white-space: nowrap;\n}\n\n.tcs-chip-modified {\n  color: var(--tcs-warn);\n  border-color: rgba(210, 153, 34, 0.45);\n  background: rgba(210, 153, 34, 0.08);\n}\n\n.tcs-chip-required {\n  color: var(--tcs-text-dim);\n}\n\n.tcs-pill {\n  font-size: 11px;\n  border-radius: 999px;\n  padding: 2px 9px;\n  white-space: nowrap;\n}\n\n.tcs-pill-on {\n  color: var(--tcs-ok);\n  background: rgba(66, 190, 101, 0.1);\n  border: 1px solid rgba(66, 190, 101, 0.35);\n}\n\n.tcs-pill-off {\n  color: var(--tcs-text-faint);\n  background: transparent;\n  border: 1px solid var(--tcs-border);\n}\n\n/* ------------------------------------------------------------ detail */\n\n.tcs-detail {\n  padding: 14px 16px 16px;\n}\n\n.tcs-enabled-row {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n  flex-wrap: wrap;\n}\n\n.tcs-detail-summary {\n  margin: 0;\n  flex: 1;\n  min-width: 240px;\n  color: var(--tcs-text-dim);\n  font-size: 12.5px;\n}\n\n/* toggle switch */\n\n.tcs-switch {\n  display: inline-flex;\n  align-items: center;\n  gap: 9px;\n  cursor: pointer;\n}\n\n.tcs-switch input {\n  position: absolute;\n  opacity: 0;\n  pointer-events: none;\n}\n\n.tcs-switch-track {\n  position: relative;\n  width: 36px;\n  height: 21px;\n  border-radius: 999px;\n  background: var(--tcs-border);\n  transition: background 140ms ease;\n  flex: none;\n}\n\n.tcs-switch-thumb {\n  position: absolute;\n  top: 2.5px;\n  left: 3px;\n  width: 16px;\n  height: 16px;\n  border-radius: 50%;\n  background: #cfd6e2;\n  transition: transform 140ms ease, background 140ms ease;\n}\n\n.tcs-switch input:checked + .tcs-switch-track {\n  background: var(--tcs-accent);\n}\n\n.tcs-switch input:checked + .tcs-switch-track .tcs-switch-thumb {\n  transform: translateX(14px);\n  background: #ffffff;\n}\n\n.tcs-switch input:focus-visible + .tcs-switch-track {\n  box-shadow: 0 0 0 3px var(--tcs-accent-soft);\n}\n\n.tcs-switch-label {\n  font-size: 13px;\n  font-weight: 600;\n}\n\n/* sections & parameters */\n\n.tcs-section {\n  margin: 18px 0 6px;\n  font-size: 11px;\n  font-weight: 600;\n  color: var(--tcs-text-faint);\n  text-transform: uppercase;\n  letter-spacing: 0.9px;\n}\n\n.tcs-params {\n  border-top: 1px solid var(--tcs-border-soft);\n}\n\n.tcs-param {\n  padding: 10px 0 12px;\n  border-bottom: 1px dashed var(--tcs-border-soft);\n}\n\n.tcs-param:last-child {\n  border-bottom: none;\n}\n\n.tcs-param-head {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n\n.tcs-param-name {\n  font-family: var(--tcs-mono);\n  font-size: 12.5px;\n  color: var(--tcs-text);\n  background: var(--tcs-panel);\n  border: 1px solid var(--tcs-border-soft);\n  border-radius: 6px;\n  padding: 1px 7px;\n}\n\n.tcs-param-type {\n  font-size: 11px;\n  color: var(--tcs-text-faint);\n  font-family: var(--tcs-mono);\n}\n\n.tcs-param-body {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  margin-top: 8px;\n  flex-wrap: wrap;\n}\n\n.tcs-param-hint {\n  margin-top: 6px;\n  color: var(--tcs-text-faint);\n  font-size: 12px;\n  line-height: 1.45;\n}\n\n.tcs-param-error {\n  margin-top: 6px;\n  color: var(--tcs-danger);\n  font-size: 12px;\n}\n\n.tcs-param.is-modified .tcs-param-name {\n  border-color: rgba(210, 153, 34, 0.5);\n}\n\n.tcs-param-readonly .tcs-param-name {\n  opacity: 0.75;\n}\n\n.tcs-muted {\n  color: var(--tcs-text-faint);\n  font-size: 12.5px;\n  margin: 8px 0;\n}\n\n.tcs-detail-actions {\n  margin-top: 16px;\n  display: flex;\n  justify-content: flex-end;\n}\n\n.tcs-btn-danger-soft {\n  color: var(--tcs-danger);\n  background: var(--tcs-danger-soft);\n  border-color: rgba(240, 85, 77, 0.35);\n}\n\n.tcs-btn-danger-soft:hover {\n  color: var(--tcs-danger);\n  border-color: var(--tcs-danger);\n  background: rgba(240, 85, 77, 0.2);\n}\n\n/* ------------------------------------------------------------ editors */\n\n.tcs-editor {\n  font: inherit;\n}\n\n.tcs-editor-text,\n.tcs-editor-select {\n  min-width: 190px;\n  padding: 7px 10px;\n  border: 1px solid var(--tcs-border);\n  border-radius: 8px;\n  background: var(--tcs-bg);\n  color: var(--tcs-text);\n  font-size: 13px;\n  outline: none;\n}\n\n.tcs-editor-text:focus,\n.tcs-editor-select:focus {\n  border-color: var(--tcs-accent);\n  box-shadow: 0 0 0 3px var(--tcs-accent-soft);\n}\n\n.tcs-editor-text::placeholder {\n  color: var(--tcs-text-faint);\n}\n\n.tcs-editor-bool {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  cursor: pointer;\n}\n\n.tcs-editor-bool input {\n  width: 16px;\n  height: 16px;\n  accent-color: var(--tcs-accent);\n  cursor: pointer;\n}\n\n.tcs-editor-bool code {\n  font-family: var(--tcs-mono);\n  font-size: 12px;\n  color: var(--tcs-text-dim);\n}\n\n.tcs-editor-readonly {\n  font-family: var(--tcs-mono);\n  font-size: 12px;\n  color: var(--tcs-text-dim);\n  max-width: 100%;\n  overflow-wrap: anywhere;\n}\n\n/* ------------------------------------------------------------ footer */\n\n.tcs-footer {\n  display: flex;\n  align-items: center;\n  gap: 18px;\n  margin-top: 34px;\n  padding-top: 14px;\n  border-top: 1px solid var(--tcs-border-soft);\n}\n\n.tcs-footer-status {\n  font-size: 12.5px;\n  color: var(--tcs-text-dim);\n}\n\n.tcs-footer-muted {\n  font-size: 11.5px;\n  color: var(--tcs-text-faint);\n}\n\n.tcs-footer-status + .tcs-footer-muted {\n  margin-left: auto;\n}\n\n/* ------------------------------------------------------------ responsive */\n\n@media (max-width: 720px) {\n  .tcs-header {\n    flex-direction: column;\n  }\n\n  .tcs-header-actions {\n    width: 100%;\n  }\n\n  .tcs-search {\n    flex: 1;\n    width: auto;\n  }\n\n  .tcs-tool {\n    flex-wrap: wrap;\n  }\n\n  .tcs-tool-meta {\n    width: 100%;\n    justify-content: flex-end;\n  }\n\n  .tcs-tool-summary {\n    display: none;\n  }\n\n  .tcs-footer {\n    flex-wrap: wrap;\n    gap: 10px;\n  }\n}\n\n/* ------------------------------------------------------------ scrollbars */\n\n.tcs ::-webkit-scrollbar {\n  width: 10px;\n  height: 10px;\n}\n\n.tcs ::-webkit-scrollbar-thumb {\n  background: var(--tcs-border);\n  border-radius: 999px;\n  border: 2px solid var(--tcs-bg);\n}\n\n.tcs ::-webkit-scrollbar-track {\n  background: transparent;\n}\n";
